create or replace function public.admin_get_product_batches() returns table(batch_number text,model_code text,product_name text,production_month date,quantity integer,created_by text,created_at timestamptz,downloaded_at timestamptz,download_count integer) language sql security definer set search_path=public as $$ select b.batch_number,pm.model_code,pm.product_name,b.production_month,b.quantity,b.created_by,b.created_at,b.downloaded_at,b.download_count from public.product_serial_batches b join public.product_models pm on pm.id=b.model_id where public.ol_product_admin_allowed() order by b.created_at desc; $$;

create or replace function public.admin_create_product_batch(p_model_code text,p_product_name text,p_capacity_kw numeric,p_warranty_months integer,p_manufacturing_date date,p_quantity integer,p_image_url text default null) returns table(model_code text,serial_number text,qr_code text,manufacturing_date date,batch_number text) language plpgsql security definer set search_path=public as $$ declare v_model public.product_models%rowtype;v_prefix text:=regexp_replace(upper(trim(p_model_code)),'[^A-Z0-9]','','g');v_month text:=to_char(p_manufacturing_date,'YYMM');v_start bigint;v_batch text:=v_prefix||'-'||to_char(p_manufacturing_date,'YYYYMMDD')||'-'||to_char(clock_timestamp(),'HH24MISSMS');i integer;v_serial text;begin if not public.ol_product_admin_allowed() then raise exception 'PRODUCT_ADMIN_ACCESS_REQUIRED';end if;if nullif(trim(p_model_code),'') is null or nullif(trim(p_product_name),'') is null then raise exception 'MODEL_AND_PRODUCT_NAME_REQUIRED';end if;if p_manufacturing_date is null then raise exception 'PRODUCTION_DATE_REQUIRED';end if;if coalesce(p_quantity,0)<1 or p_quantity>10000 then raise exception 'INVALID_QUANTITY';end if;if coalesce(p_warranty_months,0)<1 then raise exception 'INVALID_WARRANTY_MONTHS';end if;if v_prefix='' then raise exception 'INVALID_MODEL_CODE';end if;select pm.* into v_model from public.product_models pm where upper(pm.model_code)=upper(trim(p_model_code)) limit 1;if v_model.id is null then insert into public.product_models(model_code,product_name,capacity_kw,warranty_months,image_url) values(trim(p_model_code),trim(p_product_name),p_capacity_kw,p_warranty_months,nullif(trim(p_image_url),'')) returning * into v_model;else update public.product_models pm set product_name=trim(p_product_name),capacity_kw=p_capacity_kw,warranty_months=p_warranty_months,image_url=coalesce(nullif(trim(p_image_url),''),pm.image_url) where pm.id=v_model.id returning pm.* into v_model;end if;perform pg_advisory_xact_lock(hashtext(v_prefix||':'||v_month));select coalesce(max(nullif(regexp_replace(p.serial_number,'^'||v_prefix||v_month,'','')::text,'')::bigint),0)+1 into v_start from public.products p where p.model_id=v_model.id and upper(p.serial_number) like v_prefix||v_month||'%';for i in 0..p_quantity-1 loop v_serial:=v_prefix||v_month||lpad((v_start+i)::text,6,'0');insert into public.products(model_id,serial_number,qr_code,manufacturing_date,batch_number,status) values(v_model.id,v_serial,v_serial,p_manufacturing_date,v_batch,'manufactured');model_code:=v_model.model_code;serial_number:=v_serial;qr_code:=v_serial;manufacturing_date:=p_manufacturing_date;batch_number:=v_batch;return next;end loop;exception when unique_violation then raise exception 'SERIAL_NUMBER_CONFLICT';end; $$;